import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.C9sp7nFj.js";const c=JSON.parse('{"title":"ISignalDI 输入口中断","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/15. 中断指令/ISignalDI.md","filePath":"3. 指令/15. 中断指令/ISignalDI.md","lastUpdated":1778862643000}'),i={name:"3. 指令/15. 中断指令/ISignalDI.md"};function n(l,t,o,I,h,s){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="isignaldi-输入口中断" tabindex="-1">ISignalDI 输入口中断 <a class="header-anchor" href="#isignaldi-输入口中断" aria-label="Permalink to &quot;ISignalDI 输入口中断&quot;">​</a></h1><p>该指令为输入口中断指令，用于将中断检测方式设为 DI 边沿信号检测的方式，即实时监控 DI 的上升沿/下降沿信号来处理机器人相应的中断程序。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>ISignalDI(Interrupt, IO, EdgeType, [DeduplicationTime])</p><p>ISignalDI(中断标识, 端口变量, 触发边沿类型, [去重时间])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Interrupt</td><td>INTERRUPT 变量</td><td>中断唯一索引号</td><td>必填</td></tr><tr><td>IO</td><td>DI</td><td>需要监控的 DI 端口号</td><td>必填</td></tr><tr><td>EdgeType</td><td>enum(RiseEdge/DownEdge)</td><td>需要监控的 DI 边沿信号类型：RiseEdge 为上升沿信号，DownEdge 为下降沿信号</td><td>必填</td></tr><tr><td>[DeduplicationTime]</td><td>INTC 变量</td><td>指定上一次有效信号后屏蔽信号检测的时间，为 DEFAULT 时，默认去重时间为 0</td><td>可选</td></tr></tbody></table>',9)])])}const D=a(i,[["render",n]]);export{c as __pageData,D as default};
